update pages set contenu = '{"sections":[{"type":"heros","h1":"La maintenance industrielle à Lille et dans les Hauts-de-France","mecanisme":"Le Nord fait cohabiter des filières que rien ne rapproche : l''agroalimentaire dense de la métropole, le textile technique issu de Roubaix et Tourcoing, le ferroviaire et l''automobile du Valenciennois, la sidérurgie et les utilités lourdes de la façade dunkerquoise. Nos techniciens basés à Lille interviennent sur les quatre, avec la même méthode et les mêmes comptes rendus.","cta":"Faire chiffrer ma maintenance dans le Nord","telephone":"04 78 33 72 05","phraseDelai":"Nous vous rappelons dans l''heure, du lundi au vendredi de 8h00 à 18h30. Astreinte 24/24 et 7/7 en option, nuits, week-ends et jours fériés."},{"type":"chiffres","chiffres":[{"valeur":"+ 120","libelle":"clients industriels accompagnés, dont plus de 80 réguliers"},{"valeur":"+ 100","libelle":"collaborateurs, mécaniciens, électriciens, automaticiens, roboticiens"},{"valeur":"10 %","libelle":"des candidats retenus, entretien technique et comportemental, résultats partagés"},{"valeur":"10","libelle":"hubs de techniciens en France, dont un à Lille, plus notre siège lyonnais et nos agences de Montréal, Dubaï et Madrid"}]},{"type":"probleme","punchline":"Une ligne d''agroalimentaire à l''arrêt un vendredi soir près de Villeneuve-d''Ascq, et personne pour poser un diagnostic avant lundi. Le coût réel d''une maintenance sous-dimensionnée se compte en week-ends perdus.","puces":[{"accroche":"L''agroalimentaire du Nord ne rattrape pas ses heures.","texte":"Lignes de fabrication, conditionnement, froid industriel : l''arrêt se paie cash, et les saisons ne se décalent pas."},{"accroche":"Le textile technique exige une régularité absolue.","texte":"Reconversion vers le médical et le technique : une dérive machine devient un défaut qualité, pas un simple retard."},{"accroche":"Le ferroviaire et l''automobile ne tolèrent pas l''approximation.","texte":"Presses, convoyeurs, lignes cadencées du Valenciennois : la mécanique lourde punit la réparation approximative."},{"accroche":"La façade dunkerquoise tourne en continu.","texte":"Métallurgie, traitement de l''eau, valorisation des matériaux : des installations qui n''ont pas de fenêtre d''arrêt naturelle."},{"accroche":"Les offres de technicien restent affichées des mois.","texte":"De Lille à Amiens, chaque départ emporte la mémoire du site, et le préventif glisse en premier."}]},{"type":"offre","lignes":[{"prestation":"**Des gammes adaptées au lavage et au froid** : étanchéité, protection des moteurs, éléments d''usure suivis équipement par équipement.","benefice":"Vos lignes agroalimentaires tiennent la cadence sans réparations à répétition."},{"prestation":"**Un préventif planifié, gammes et périodicités écrites**, calé sur vos heures de fonctionnement.","benefice":"L''arrêt subi recule, et la charge de vos équipes internes se lisse."},{"prestation":"**Le champ technique complet** : [mécanique](/expertises/mecanique/), [électricité](/expertises/electrique/), [automatisme](/expertises/automatisme/), [hydraulique](/expertises/hydraulique/), [pneumatique](/expertises/pneumatique/), [soudure](/expertises/soudure/).","benefice":"Un seul contrat pour un parc qui mélange presses, convoyeurs, extrudeuses et utilités."},{"prestation":"**Les utilités traitées comme des machines de production** : air comprimé, fluides, eau de process, distribution électrique.","benefice":"Vous fermez la cause première de bien des arrêts de ligne, seuils d''alerte compris."},{"prestation":"**Astreinte 24/24 et 7/7 en option**, nuits, week-ends et jours fériés.","benefice":"Une alerte du dimanche soir trouve un technicien, pas un répondeur."},{"prestation":"**Un hub de techniciens à Lille** : la couverture du Nord est portée par des techniciens basés sur le bassin, appuyés par le siège lyonnais et le reste du réseau.","benefice":"Vous avez des techniciens du Nord sur vos machines, et une organisation qui tient derrière eux."},{"prestation":"**Les grands projets pris en charge** : [transfert de production](/offres/chantier/transfert-de-production/), [remise en état](/offres/retrofit/remise-en-etat/), [arrêt planifié](/offres/arret-technique/).","benefice":"Regroupement d''ateliers ou déménagement de ligne : un chef de projet unique, des jalons datés."}],"prose":[{"texte":"La logistique du bassin, entrepôts, messagerie et plateformes des grands axes, a sa page dédiée : [maintenance des équipements logistiques](/secteurs/logistique/)."}]},{"type":"deroule","etapes":[{"titre":"L''appel","texte":"Un échange suffit. Vous exposez la panne ou le besoin au 04 78 33 72 05, et le rappel arrive dans l''heure aux horaires ouvrés : équipements, accès, habilitations."},{"titre":"Le devis","texte":"Périmètre, moyens, conditions d''intervention. Le cadre s''écrit avant, l''exceptionnel se chiffre en amont."},{"titre":"L''intervention","texte":"Accueil sécurité, plan de prévention, consignation, puis diagnostic et appui à distance du groupe."},{"titre":"La cause racine","texte":"Réparer vite ne suffit pas. L''analyse cherche pourquoi la défaillance est arrivée, pour qu''elle ne revienne pas au même point."},{"titre":"Le compte rendu","texte":"Actions, pièces, résultats et préconisations, versés dans votre GMAO. Les données restent chez vous."},{"titre":"Le suivi","texte":"Indicateurs mis à jour à chaque visite, plan d''action tenu, revue périodique avec votre responsable maintenance."}]},{"type":"garanties","puces":[{"accroche":"Vous pilotez, nous exécutons","texte":"vos priorités, vos règles de sécurité, votre GMAO. Nos techniciens s''intègrent à votre organisation, ils ne la remplacent pas."},{"accroche":"La compétence se prouve sur pièces","texte":"entretien technique et comportemental, un candidat sur dix retenu, résultats remis avant la première visite sur votre site."},{"accroche":"Une montée en charge à votre rythme","texte":"un dépannage d''essai, puis un premier chantier, puis un contrat quand les chiffres le justifient. Rien n''oblige à tout confier d''un coup."}]},{"type":"cta","question":"Besoin d''un diagnostic fiable le vendredi soir plutôt que le lundi matin ?","bouton":"Faire chiffrer ma maintenance dans le Nord","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure."},{"type":"preuves","preuves":[{"titre":"Deux techniciens intégrés en 3x8 sur les lignes liquides et poudre du site de Steenvoorde","texte":"agroalimentaire du Nord","lienLibelle":"Étude de cas DANONE : lignes de production","lienHref":"/preuves/danone-lignes-de-production/"},{"titre":"Premier contrat hors de France depuis octobre 2024","texte":"techniciens en renfort sur un site agroalimentaire belge, de l''autre côté de la frontière","lienLibelle":"Étude de cas McCAIN : Belgique","lienHref":"/preuves/mccain-belgique/"},{"titre":"Un technicien polyvalent intégré sur un site papier et emballage en forte cadence","texte":"2025 à 2026","lienLibelle":"Étude de cas VPK : maintenance de site","lienHref":"/preuves/vpk/"},{"titre":"Deux techniciens dédiés à la maintenance curative des convoyeurs, trieurs et packaging","texte":"en poste sur site, transport","lienLibelle":"Étude de cas GLS : maintenance curative","lienHref":"/preuves/gls-maintenance-curative/"},{"titre":"1 à 3 techniciens en renfort permanent sur plusieurs sites de production","texte":", depuis octobre 2024","lienLibelle":"Étude de cas GROUPE ATLANTIC : renfort d''équipes","lienHref":"/preuves/groupe-atlantic/"}]},{"type":"objections","questions":[{"question":"Êtes-vous vraiment implantés à Lille ?","reponse":"Oui. Lille est l''un de nos 10 hubs de techniciens en France : des techniciens basés sur le bassin, pas une équipe envoyée de loin. S''y ajoutent notre siège lyonnais et nos agences de Montréal, Dubaï et Madrid pour les compétences rares."},{"question":"Couvrez-vous toute la région des Hauts-de-France ?","reponse":"Oui : la métropole lilloise, Villeneuve-d''Ascq, Roubaix, Tourcoing, le Valenciennois, Dunkerque et jusqu''à Amiens. La Normandie proche et l''Île-de-France complètent le maillage. Au-delà, les autres hubs de techniciens prennent le relais dans les grandes villes de France, avec le même niveau d''exigence."},{"question":"Intervenez-vous en urgence à Lille ?","reponse":"Votre demande est rappelée dans l''heure aux horaires ouvrés, et l''astreinte 24/24 et 7/7 prend le relais la nuit, le week-end et les jours fériés. Nous n''affichons aucun délai d''intervention de façade : le circuit d''appel et les priorités s''écrivent au devis, équipement par équipement."},{"question":"Combien coûte un contrat de maintenance ?","reponse":"Zéro arrêt est chiffré sur devis, avec trois niveaux de couverture et un engagement type de 6 mois renouvelable. Le chiffrage s''appuie sur un état des lieux : équipements couverts, fréquences, utilités incluses, étendue de l''astreinte. Le diagnostic de départ est gratuit, et les dates de visite sont posées à l''avance."},{"question":"Pouvez-vous détacher un technicien à demeure ?","reponse":"Oui, c''est l''offre [résidence](/offres/residence/) : un salarié Migen qui prend un poste dans votre équipe, encadré par un référent, opérationnel en 2 à 3 semaines. Un départ ou un arrêt ne vous laisse pas sans personne, un profil équivalent reprend le poste, briefé sur vos machines."},{"question":"Traitez-vous les réseaux et utilités industrielles ?","reponse":"Oui : air comprimé, réseaux de fluides, eau de process, distribution électrique. Les utilités sont souvent la cause première d''un arrêt de ligne, et nous les intégrons au préventif au même titre que les machines de production, seuils d''alerte compris."},{"question":"Confier notre maintenance, est-ce perdre le contrôle de notre outil ?","reponse":"Non, si le cadre est écrit. Périmètre défini, comptes rendus partagés, indicateurs mis à jour à chaque visite, plan d''action suivi. Notre ressource [externaliser sa maintenance](/ressources/livres-blancs/externaliser-sa-maintenance/) détaille la méthode et les points à verrouiller avant de signer."}]},{"type":"ctaFinal","question":"Besoin de fiabiliser un parc du Nord avant la prochaine saison haute ?","bouton":"Faire chiffrer ma maintenance dans le Nord","rappel":"ou appelez le 04 78 33 72 05, rappel dans l''heure aux horaires ouvrés."}]}'::jsonb where path = '/implantations/lille/';
